import{_ as t,a0 as m,w as u,s as l,ao as p,I as d,x as o,a1 as n,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"關於 /dev/urandom 的流言終結 | LCTT x X-CMD","titleTemplate":false,"description":"關於 /dev/urandom 的流言終結 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關於 /dev/urandom 的流言終結 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關於 /dev/urandom 的流言終結 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20161106 Myths about -dev-urandom","title":"關於 /dev/urandom 的流言終結","tag":"201905","desc":""},"relativePath":"201905/20161106 Myths about -dev-urandom.md","filePath":"[post].md"}'),i={name:"201905/20161106 Myths about -dev-urandom.md"};function c(s,e,v,b,h,x){const a=m("Link");return u(),l("div",null,[e[28]||(e[28]=p('<h1 id="關於-dev-urandom-的流言終結" tabindex="-1">關於 /dev/urandom 的流言終結 <a class="header-anchor" href="#關於-dev-urandom-的流言終結" aria-label="Permalink to “關於 /dev/urandom 的流言終結”">​</a></h1><p>有很多關於 <code>/dev/urandom</code> 和 <code>/dev/random</code> 的流言在坊間不斷流傳。然而流言終究是流言。</p><blockquote><p>本篇文章裏針對的都是近來的 Linux 操作系統，其它類 Unix 操作系統不在討論範圍內。</p></blockquote><p><strong><code>/dev/urandom</code> 不安全。加密用途必須使用 <code>/dev/random</code></strong></p><p><em>事實</em>：<code>/dev/urandom</code> 才是類 Unix 操作系統下推薦的加密種子。</p><p><strong><code>/dev/urandom</code> 是<ruby>偽隨機數生成器<rt>pseudo random number generator</rt></ruby>（PRND），而 <code>/dev/random</code> 是“真”隨機數生成器。</strong></p><p><em>事實</em>：它們兩者本質上用的是同一種 CSPRNG （一種密碼學偽隨機數生成器）。它們之間細微的差別和“真”“不真”隨機完全無關。（參見：“Linux 隨機數生成器的構架”一節）</p><p><strong><code>/dev/random</code> 在任何情況下都是密碼學應用更好地選擇。即便 <code>/dev/urandom</code> 也同樣安全，我們還是不應該用它。</strong></p><p><em>事實</em>：<code>/dev/random</code> 有個很噁心人的問題：它是阻塞的。（參見：“阻塞有什麼問題？”一節）（LCTT 譯註：意味着請求都得逐個執行，等待前一個請求完成）</p><p><strong>但阻塞不是好事嗎！<code>/dev/random</code> 只會給出電腦收集的信息熵足以支持的隨機量。<code>/dev/urandom</code> 在用完了所有熵的情況下還會不斷吐出不安全的隨機數給你。</strong></p><p><em>事實</em>：這是誤解。就算我們不去考慮應用層面後續對隨機種子的用法，“用完信息熵池”這個概念本身就不存在。僅僅 256 位的熵就足以生成計算上安全的隨機數很長、很長的一段時間了。（參見：“那熵池快空了的情況呢？”一節）</p><p>問題的關鍵還在後頭：<code>/dev/random</code> 怎麼知道有系統會<em>多少</em>可用的信息熵？接着看！</p><p><strong>但密碼學家老是討論重新選種子（re-seeding）。這難道不和上一條衝突嗎？</strong></p><p><em>事實</em>：你説的也沒錯！某種程度上吧。確實，隨機數生成器一直在使用系統信息熵的狀態重新選種。但這麼做（一部分）是因為別的原因。（參見：“重新選種”一節）</p><p>這樣説吧，我沒有説引入新的信息熵是壞的。更多的熵肯定更好。我只是説在熵池低的時候阻塞是沒必要的。</p><p><strong>好，就算你説的都對，但是 <code>/dev/(u)random</code> 的 man 頁面和你説的也不一樣啊！到底有沒有專家同意你説的這堆啊？</strong></p><p><em>事實</em>：其實 man 頁面和我説的不衝突。它看似好像在説 <code>/dev/urandom</code> 對密碼學用途來説不安全，但如果你真的理解這堆密碼學術語你就知道它説的並不是這個意思。（參見：“random 和 urandom 的 man 頁面”一節）</p><p>man 頁面確實説在一些情況下推薦使用 <code>/dev/random</code> （我覺得也沒問題，但絕對不是説必要的），但它也推薦在大多數“一般”的密碼學應用下使用 <code>/dev/urandom</code> 。</p><p>雖然訴諸權威一般來説不是好事，但在密碼學這麼嚴肅的事情上，和專家統一意見是很有必要的。</p><p>所以説呢，還確實有一些<em>專家</em>和我的一件事一致的：<code>/dev/urandom</code> 就應該是類 UNIX 操作系統下密碼學應用的首選。顯然的，是他們的觀點説服了我而不是反過來的。（參見：“正道”一節）</p><hr><p>難以相信嗎？覺得我肯定錯了？讀下去看我能不能説服你。</p><p>我嘗試不講太高深的東西，但是有兩點內容必須先提一下才能讓我們接着論證觀點。</p><p>首當其衝的，<em>什麼是隨機性</em>，或者更準確地：我們在探討什麼樣的隨機性？（參見：“真隨機”一節）</p><p>另外一點很重要的是，我<em>沒有嘗試以説教的態度</em>對你們寫這段話。我寫這篇文章是為了日後可以在討論起的時候指給別人看。比 140 字長（LCTT 譯註：推特長度）。這樣我就不用一遍遍重複我的觀點了。能把論點磨鍊成一篇文章本身就很有助於將來的討論。（參見：“你是在説我笨？！”一節）</p><p>並且我非常樂意聽到不一樣的觀點。但我只是認為單單地説 <code>/dev/urandom</code> 壞是不夠的。你得能指出到底有什麼問題，並且剖析它們。</p><h3 id="你是在説我笨" tabindex="-1">你是在説我笨？！ <a class="header-anchor" href="#你是在説我笨" aria-label="Permalink to “你是在説我笨？！”">​</a></h3><p>絕對沒有！</p><p>事實上我自己也相信了 “<code>/dev/urandom</code> 是不安全的” 好些年。這幾乎不是我們的錯，因為那麼德高望重的人在 Usenet、論壇、推特上跟我們重複這個觀點。甚至<em>連 man 手冊</em>都似是而非地説着。我們當年怎麼可能鄙視諸如“信息熵太低了”這種看上去就很讓人信服的觀點呢？（參見：“random 和 urandom 的 man 頁面”一節）</p><p>整個流言之所以如此廣為流傳不是因為人們太蠢，而是因為但凡有點關於信息熵和密碼學概念的人都會覺得這個説法很有道理。直覺似乎都在告訴我們這流言講的很有道理。很不幸直覺在密碼學裏通常不管用，這次也一樣。</p><h3 id="真隨機" tabindex="-1">真隨機 <a class="header-anchor" href="#真隨機" aria-label="Permalink to “真隨機”">​</a></h3><p>隨機數是“真正隨機”是什麼意思？</p><p>我不想搞的太複雜以至於變成哲學範疇的東西。這種討論很容易走偏因為對於隨機模型大家見仁見智，討論很快變得毫無意義。</p><p>在我看來“真隨機”的“試金石”是量子效應。一個光子穿過或不穿過一個半透鏡。或者觀察一個放射性粒子衰變。這類東西是現實世界最接近真隨機的東西。當然，有些人也不相信這類過程是真隨機的，或者這個世界根本不存在任何隨機性。這個就百家爭鳴了，我也不好多説什麼了。</p><p>密碼學家一般都會通過不去討論什麼是“真隨機”來避免這種哲學辯論。他們更關心的是<ruby>不可預測性<rt>unpredictability</rt></ruby>。只要沒有<em>任何</em>方法能猜出下一個隨機數就可以了。所以當你以密碼學應用為前提討論一個隨機數好不好的時候，在我看來這才是最重要的。</p><p>無論如何，我不怎麼關心“哲學上安全”的隨機數，這也包括別人嘴裏的“真”隨機數。</p><h3 id="兩種安全-一種有用" tabindex="-1">兩種安全，一種有用 <a class="header-anchor" href="#兩種安全-一種有用" aria-label="Permalink to “兩種安全，一種有用”">​</a></h3><p>但就讓我們退一步説，你有了一個“真”隨機變量。你下一步做什麼呢？</p><p>你把它們打印出來然後掛在牆上來展示量子宇宙的美與和諧？牛逼！我支持你。</p><p>但是等等，你説你要<em>用</em>它們？做密碼學用途？額，那這就廢了，因為這事情就有點複雜了。</p><p>事情是這樣的，你的真隨機、量子力學加護的隨機數即將被用進不理想的現實世界算法裏去。</p><p>因為我們使用的幾乎所有的算法都並不是<ruby>信息論安全性<rt>information-theoretic security </rt></ruby>的。它們“只能”提供<strong>計算意義上的安全</strong>。我能想到為數不多的例外就只有 Shamir 密鑰分享和<ruby>一次性密碼本<rt>One-time pad</rt></ruby>（OTP）算法。並且就算前者是名副其實的（如果你實際打算用的話），後者則毫無可行性可言。</p><p>但所有那些大名鼎鼎的密碼學算法，AES、RSA、Diffie-Hellman、橢圓曲線，還有所有那些加密軟件包，OpenSSL、GnuTLS、Keyczar、你的操作系統的加密 API，都僅僅是計算意義上安全的。</p><p>那區別是什麼呢？信息論安全的算法肯定是安全的，絕對是，其它那些的算法都可能在理論上被擁有無限計算力的窮舉破解。我們依然愉快地使用它們是因為全世界的計算機加起來都不可能在宇宙年齡的時間裏破解，至少現在是這樣。而這就是我們文章裏説的“不安全”。</p><p>除非哪個聰明的傢伙破解了算法本身 —— 在只需要更少量計算力、在今天可實現的計算力的情況下。這也是每個密碼學家夢寐以求的聖盃：破解 AES 本身、破解 RSA 本身等等。</p><p>所以現在我們來到了更底層的東西：隨機數生成器，你堅持要“真隨機”而不是“偽隨機”。但是沒過一會兒你的真隨機數就被喂進了你極為鄙視的偽隨機算法裏了！</p><p>真相是，如果我們最先進的哈希算法被破解了，或者最先進的分組加密算法被破解了，你得到的這些“哲學上不安全”的隨機數甚至無所謂了，因為反正你也沒有安全的應用方法了。</p><p>所以把計算性上安全的隨機數餵給你的僅僅是計算性上安全的算法就可以了，換而言之，用 <code>/dev/urandom</code>。</p><h3 id="linux-隨機數生成器的構架" tabindex="-1">Linux 隨機數生成器的構架 <a class="header-anchor" href="#linux-隨機數生成器的構架" aria-label="Permalink to “Linux 隨機數生成器的構架”">​</a></h3><h4 id="一種錯誤的看法" tabindex="-1">一種錯誤的看法 <a class="header-anchor" href="#一種錯誤的看法" aria-label="Permalink to “一種錯誤的看法”">​</a></h4><p>你對內核的隨機數生成器的理解很可能是像這樣的：</p><p><img src="https://www.2uo.de/_media/wiki:structure-no.png" alt="image: mythical structure of the kernel&#39;s random number generator"></p><p>“真正的隨機性”，儘管可能有點瑕疵，進入操作系統然後它的熵立刻被加入內部熵計數器。然後經過“矯偏”和“漂白”之後它進入內核的熵池，然後 <code>/dev/random</code> 和 <code>/dev/urandom</code> 從裏面生成隨機數。</p><p>“真”隨機數生成器，<code>/dev/random</code>，直接從池裏選出隨機數，如果熵計數器表示能滿足需要的數字大小，那就吐出數字並且減少熵計數。如果不夠的話，它會阻塞程序直至有足夠的熵進入系統。</p><p>這裏很重要一環是 <code>/dev/random</code> 幾乎只是僅經過必要的“漂白”後就直接把那些進入系統的隨機性吐了出來，不經扭曲。</p><p>而對 <code>/dev/urandom</code> 來説，事情是一樣的。除了當沒有足夠的熵的時候，它不會阻塞，而會從一直在運行的偽隨機數生成器（當然，是密碼學安全的，CSPRNG）裏吐出“低質量”的隨機數。這個 CSPRNG 只會用“真隨機數”生成種子一次（或者好幾次，這不重要），但你不能特別相信它。</p><p>在這種對隨機數生成的理解下，很多人會覺得在 Linux 下儘量避免 <code>/dev/urandom</code> 看上去有那麼點道理。</p><p>因為要麼你有足夠多的熵，你會相當於用了 <code>/dev/random</code>。要麼沒有，那你就會從幾乎沒有高熵輸入的 CSPRNG 那裏得到一個低質量的隨機數。</p><p>看上去很邪惡是吧？很不幸的是這種看法是完全錯誤的。實際上，隨機數生成器的構架更像是下面這樣的。</p><h4 id="更好地簡化" tabindex="-1">更好地簡化 <a class="header-anchor" href="#更好地簡化" aria-label="Permalink to “更好地簡化”">​</a></h4><h5 id="linux-4-8-之前" tabindex="-1">Linux 4.8 之前 <a class="header-anchor" href="#linux-4-8-之前" aria-label="Permalink to “Linux 4.8 之前”">​</a></h5><p><img src="https://www.2uo.de/_media/wiki:structure-yes.png" alt="image: actual structure of the kernel&#39;s random number generator before Linux 4.8"></p><p>你看到最大的區別了嗎？CSPRNG 並不是和隨機數生成器一起跑的，它在 <code>/dev/urandom</code> 需要輸出但熵不夠的時候進行填充。CSPRNG 是整個隨機數生成過程的內部組件之一。從來就沒有什麼 <code>/dev/random</code> 直接從池裏輸出純純的隨機性。每個隨機源的輸入都在 CSPRNG 裏充分混合和散列過了，這一切都發生在實際變成一個隨機數，被 <code>/dev/urandom</code> 或者 <code>/dev/random</code> 吐出去之前。</p><p>另外一個重要的區別是這裏沒有熵計數器的任何事情，只有預估。一個源給你的熵的量並不是什麼很明確能直接得到的數字。你得預估它。注意，如果你太樂觀地預估了它，那 <code>/dev/random</code> 最重要的特性——只給出熵允許的隨機量——就蕩然無存了。很不幸的，預估熵的量是很困難的。</p><blockquote><p>這是個很粗糙的簡化。實際上不僅有一個，而是三個熵池。一個主池，另一個給 <code>/dev/random</code>，還有一個給 <code>/dev/urandom</code>，後兩者依靠從主池裏獲取熵。這三個池都有各自的熵計數器，但二級池（後兩個）的計數器基本都在 0 附近，而“新鮮”的熵總在需要的時候從主池流過來。同時還有好多混合和迴流進系統在同時進行。整個過程對於這篇文檔來説都過於複雜了，我們跳過。</p></blockquote><p>Linux 內核只使用事件的到達時間來預估熵的量。根據模型，它通過多項式插值來預估實際的到達時間有多“出乎意料”。這種多項式插值的方法到底是不是好的預估熵量的方法本身就是個問題。同時硬件情況會不會以某種特定的方式影響到達時間也是個問題。而所有硬件的取樣率也是個問題，因為這基本上就直接決定了隨機數到達時間的顆粒度。</p><p>説到最後，至少現在看來，內核的熵預估還是不錯的。這也意味着它比較保守。有些人會具體地討論它有多好，這都超出我的腦容量了。就算這樣，如果你堅持不想在沒有足夠多的熵的情況下吐出隨機數，那你看到這裏可能還會有一絲緊張。我睡的就很香了，因為我不關心熵預估什麼的。</p><p>最後要明確一下：<code>/dev/random</code> 和 <code>/dev/urandom</code> 都是被同一個 CSPRNG 飼餵的。只有它們在用完各自熵池（根據某種預估標準）的時候，它們的行為會不同：<code>/dev/random</code> 阻塞，<code>/dev/urandom</code> 不阻塞。</p><h5 id="linux-4-8-以後" tabindex="-1">Linux 4.8 以後 <a class="header-anchor" href="#linux-4-8-以後" aria-label="Permalink to “Linux 4.8 以後”">​</a></h5><p><img src="https://www.2uo.de/_media/wiki:structure-new.png" alt="image: actual structure of the kernel&#39;s random number generator from Linux 4.8 onward"></p><p>在 Linux 4.8 裏，<code>/dev/random</code> 和 <code>/dev/urandom</code> 的等價性被放棄了。現在 <code>/dev/urandom</code> 的輸出不來自於熵池，而是直接從 CSPRNG 來。</p><p><em>我們很快會理解</em>為什麼這不是一個安全問題。（參見：“CSPRNG 沒問題”一節）</p><h3 id="阻塞有什麼問題" tabindex="-1">阻塞有什麼問題？ <a class="header-anchor" href="#阻塞有什麼問題" aria-label="Permalink to “阻塞有什麼問題？”">​</a></h3><p>你有沒有需要等着 <code>/dev/random</code> 來吐隨機數？比如在虛擬機裏生成一個 PGP 密鑰？或者訪問一個在生成會話密鑰的網站？</p><p>這些都是問題。阻塞本質上會降低可用性。換而言之你的系統不干你讓它乾的事情。不用我説，這是不好的。要是它不幹活你幹嘛搭建它呢？</p><blockquote><p>我在工廠自動化裏做過和安全相關的系統。猜猜看安全系統失效的主要原因是什麼？操作問題。就這麼簡單。很多安全措施的流程讓工人惱火了。比如時間太長，或者太不方便。你要知道人很會找捷徑來“解決”問題。</p></blockquote><p>但其實有個更深刻的問題：人們不喜歡被打斷。它們會找一些繞過的方法，把一些詭異的東西接在一起僅僅因為這樣能用。一般人根本不知道什麼密碼學什麼亂七八糟的，至少正常的人是這樣吧。</p><p>為什麼不禁止調用 <code>random()</code>？為什麼不隨便在論壇上找個人告訴你用寫奇異的 ioctl 來增加熵計數器呢？為什麼不乾脆就把 SSL 加密給關了算了呢？</p><p>到頭來如果東西太難用的話，你的用户就會被迫開始做一些降低系統安全性的事情——你甚至不知道它們會做些什麼。</p><p>我們很容易會忽視可用性之類的重要性。畢竟安全第一對吧？所以比起犧牲安全，不可用、難用、不方便都是次要的？</p><p>這種二元對立的想法是錯的。阻塞不一定就安全了。正如我們看到的，<code>/dev/urandom</code> 直接從 CSPRNG 裏給你一樣好的隨機數。用它不好嗎！</p><h3 id="csprng-沒問題" tabindex="-1">CSPRNG 沒問題 <a class="header-anchor" href="#csprng-沒問題" aria-label="Permalink to “CSPRNG 沒問題”">​</a></h3><p>現在情況聽上去很慘淡。如果連高質量的 <code>/dev/random</code> 都是從一個 CSPRNG 裏來的，我們怎麼敢在高安全性的需求上使用它呢？</p><p>實際上，“看上去隨機”是現存大多數密碼學基礎組件的基本要求。如果你觀察一個密碼學哈希的輸出，它一定得和隨機的字符串不可區分，密碼學家才會認可這個算法。如果你生成一個分組加密，它的輸出（在你不知道密鑰的情況下）也必須和隨機數據不可區分才行。</p><p>如果任何人能比暴力窮舉要更有效地破解一個加密，比如它利用了某些 CSPRNG 偽隨機的弱點，那這就又是老一套了：一切都廢了，也別談後面的了。分組加密、哈希，一切都是基於某個數學算法，比如 CSPRNG。所以別害怕，到頭來都一樣。</p><h3 id="那熵池快空了的情況呢" tabindex="-1">那熵池快空了的情況呢？ <a class="header-anchor" href="#那熵池快空了的情況呢" aria-label="Permalink to “那熵池快空了的情況呢？”">​</a></h3><p>毫無影響。</p><p>加密算法的根基建立在攻擊者不能預測輸出上，只要最一開始有足夠的隨機性（熵）就行了。“足夠”的下限可以是 256 位，不需要更多了。</p><p>介於我們一直在很隨意的使用“熵”這個概念，我用“位”來量化隨機性希望讀者不要太在意細節。像我們之前討論的那樣，內核的隨機數生成器甚至沒法精確地知道進入系統的熵的量。只有一個預估。而且這個預估的準確性到底怎麼樣也沒人知道。</p><h3 id="重新選種" tabindex="-1">重新選種 <a class="header-anchor" href="#重新選種" aria-label="Permalink to “重新選種”">​</a></h3><p>但如果熵這麼不重要，為什麼還要有新的熵一直被收進隨機數生成器裏呢？</p>',91)),d("blockquote",null,[d("p",null,[e[1]||(e[1]=o("djb ",-1)),n(a,{href:"http://blog.cr.yp.to/20140205-entropy.html"},{default:r(()=>[...e[0]||(e[0]=[o("提到",-1)])]),_:1}),e[2]||(e[2]=o(" 太多的熵甚至可能會起到反效果。",-1))])]),e[29]||(e[29]=p('<p>首先，一般不會這樣。如果你有很多隨機性可以拿來用，用就對了！</p><p>但隨機數生成器時不時要重新選種還有別的原因：</p><p>想像一下如果有個攻擊者獲取了你隨機數生成器的所有內部狀態。這是最壞的情況了，本質上你的一切都暴露給攻擊者了。</p><p>你已經涼了，因為攻擊者可以計算出所有未來會被輸出的隨機數了。</p><p>但是，如果不斷有新的熵被混進系統，那內部狀態會再一次變得隨機起來。所以隨機數生成器被設計成這樣有些“自愈”能力。</p><p>但這是在給內部狀態引入新的熵，這和阻塞輸出沒有任何關係。</p><h3 id="random-和-urandom-的-man-頁面" tabindex="-1">random 和 urandom 的 man 頁面 <a class="header-anchor" href="#random-和-urandom-的-man-頁面" aria-label="Permalink to “random 和 urandom 的 man 頁面”">​</a></h3><p>這兩個 man 頁面在嚇唬程序員方面很有建樹：</p><blockquote><p>從 <code>/dev/urandom</code> 讀取數據不會因為需要更多熵而阻塞。這樣的結果是，如果熵池裏沒有足夠多的熵，取決於驅動使用的算法，返回的數值在理論上有被密碼學攻擊的可能性。發動這樣攻擊的步驟並沒有出現在任何公開文獻當中，但這樣的攻擊從理論上講是可能存在的。如果你的應用擔心這類情況，你應該使用 <code>/dev/random</code>。</p></blockquote><blockquote><blockquote><p>實際上已經有 <code>/dev/random</code> 和 <code>/dev/urandom</code> 的 Linux 內核 man 頁面的更新版本。不幸的是，隨便一個網絡搜索出現我在結果頂部的仍然是舊的、有缺陷的版本。此外，許多 Linux 發行版仍在發佈舊的 man 頁面。所以不幸的是，這一節需要在這篇文章中保留更長的時間。我很期待刪除這一節！</p></blockquote></blockquote><p>沒有“公開的文獻”描述，但是 NSA 的小賣部裏肯定賣這種攻擊手段是吧？如果你真的真的很擔心（你應該很擔心），那就用 <code>/dev/random</code> 然後所有問題都沒了？</p><p>然而事實是，可能某個什麼情報局有這種攻擊，或者某個什麼邪惡黑客組織找到了方法。但如果我們就直接假設這種攻擊一定存在也是不合理的。</p><p>而且就算你想給自己一個安心，我要給你潑個冷水：AES、SHA-3 或者其它什麼常見的加密算法也沒有“公開文獻記述”的攻擊手段。難道你也不用這幾個加密算法了？這顯然是可笑的。</p><p>我們在回到 man 頁面説：“使用 <code>/dev/random</code>”。我們已經知道了，雖然 <code>/dev/urandom</code> 不阻塞，但是它的隨機數和 <code>/dev/random</code> 都是從同一個 CSPRNG 裏來的。</p><p>如果你真的需要信息論安全性的隨機數（你不需要的，相信我），那才有可能成為唯一一個你需要等足夠熵進入 CSPRNG 的理由。而且你也不能用 <code>/dev/random</code>。</p><p>man 頁面有毒，就這樣。但至少它還稍稍挽回了一下自己：</p><blockquote><p>如果你不確定該用 <code>/dev/random</code> 還是 <code>/dev/urandom</code> ，那你可能應該用後者。通常來説，除了需要長期使用的 GPG/SSL/SSH 密鑰以外，你總該使用<code>/dev/urandom</code> 。</p></blockquote>',17)),d("blockquote",null,[d("blockquote",null,[d("p",null,[e[4]||(e[4]=o("該手冊頁的",-1)),n(a,{href:"http://man7.org/linux/man-pages/man4/random.4.html"},{default:r(()=>[...e[3]||(e[3]=[o("當前更新版本",-1)])]),_:1}),e[5]||(e[5]=o("毫不含糊地説：",-1))])])]),e[30]||(e[30]=p('<blockquote><blockquote><p><code>/dev/random</code> 接口被認為是遺留接口，並且 <code>/dev/urandom</code> 在所有用例中都是首選和足夠的，除了在啓動早期需要隨機性的應用程序；對於這些應用程序，必須替代使用 <code>getrandom(2)</code>，因為它將阻塞，直到熵池初始化完成。</p></blockquote></blockquote><p>行。我覺得沒必要，但如果你真的要用 <code>/dev/random</code> 來生成 “長期使用的密鑰”，用就是了也沒人攔着！你可能需要等幾秒鐘或者敲幾下鍵盤來增加熵，但這沒什麼問題。</p><p>但求求你們，不要就因為“你想更安全點”就讓連個郵件服務器要掛起半天。</p><h3 id="正道" tabindex="-1">正道 <a class="header-anchor" href="#正道" aria-label="Permalink to “正道”">​</a></h3><p>本篇文章裏的觀點顯然在互聯網上是“小眾”的。但如果問一個真正的密碼學家，你很難找到一個認同阻塞 <code>/dev/random</code> 的人。</p>',5)),d("p",null,[e[7]||(e[7]=o("比如我們看看 ",-1)),n(a,{href:"http://www.mail-archive.com/cryptography@randombit.net/msg04763.html"},{default:r(()=>[...e[6]||(e[6]=[o("Daniel Bernstein",-1)])]),_:1}),e[8]||(e[8]=o("（即著名的 djb）的看法：",-1))]),e[31]||(e[31]=d("blockquote",null,[d("p",null,[o("我們密碼學家對這種胡亂迷信行為表示不負責。你想想，寫 "),d("code",null,"/dev/random"),o(" man 頁面的人好像同時相信：")]),d("ul",null,[d("li",null,[o("(1) 我們不知道如何用一個 256 位長的 "),d("code",null,"/dev/random"),o(" 的輸出來生成一個無限長的隨機密鑰串流（這是我們需要 "),d("code",null,"/dev/urandom"),o(" 吐出來的），但與此同時")]),d("li",null,"(2) 我們卻知道怎麼用單個密鑰來加密一條消息（這是 SSL，PGP 之類乾的事情）")]),d("p",null,"對密碼學家來説這甚至都不好笑了")],-1)),d("p",null,[e[10]||(e[10]=o("或者 ",-1)),n(a,{href:"http://security.stackexchange.com/questions/3936/is-a-rand-from-dev-urandom-secure-for-a-login-key/3939#3939"},{default:r(()=>[...e[9]||(e[9]=[o("Thomas Pornin",-1)])]),_:1}),e[11]||(e[11]=o(" 的看法，他也是我在 stackexchange 上見過最樂於助人的一位：",-1))]),e[32]||(e[32]=d("blockquote",null,[d("p",null,[o("簡單來説，是的。展開説，答案還是一樣。"),d("code",null,"/dev/urandom"),o(" 生成的數據可以説和真隨機完全無法區分，至少在現有科技水平下。使用比 "),d("code",null,"/dev/urandom"),o(" “更好的“隨機性毫無意義，除非你在使用極為罕見的“信息論安全”的加密算法。這肯定不是你的情況，不然你早就説了。")]),d("p",null,[o("urandom 的 man 頁面多多少少有些誤導人，或者乾脆可以説是錯的——特別是當它説 "),d("code",null,"/dev/urandom"),o(" 會“用完熵”以及 “"),d("code",null,"/dev/random"),o(" 是更好的”那幾句話；")])],-1)),d("p",null,[e[13]||(e[13]=o("或者 ",-1)),n(a,{href:"http://sockpuppet.org/blog/2014/02/25/safely-generate-random-numbers/"},{default:r(()=>[...e[12]||(e[12]=[o("Thomas Ptacek",-1)])]),_:1}),e[14]||(e[14]=o(" 的看法，他不設計密碼算法或者密碼學系統，但他是一家名聲在外的安全諮詢公司的創始人，這家公司負責很多滲透和破解爛密碼學算法的測試：",-1))]),e[33]||(e[33]=p('<blockquote><p>用 urandom。用 urandom。用 urandom。用 urandom。用 urandom。</p></blockquote><h3 id="沒有完美" tabindex="-1">沒有完美 <a class="header-anchor" href="#沒有完美" aria-label="Permalink to “沒有完美”">​</a></h3><p><code>/dev/urandom</code> 不是完美的，問題分兩層：</p><p>在 Linux 上，不像 FreeBSD，<code>/dev/urandom</code> 永遠不阻塞。記得安全性取決於某個最一開始決定的隨機性？種子？</p><p>Linux 的 <code>/dev/urandom</code> 會很樂意給你吐點不怎麼隨機的隨機數，甚至在內核有機會收集一丁點熵之前。什麼時候有這種情況？當你係統剛剛啓動的時候。</p><p>FreeBSD 的行為更正確點：<code>/dev/random</code> 和 <code>/dev/urandom</code> 是一樣的，在系統啓動的時候 <code>/dev/random</code> 會阻塞到有足夠的熵為止，然後它們都再也不阻塞了。</p><blockquote><p>與此同時 Linux 實行了一個新的<ruby>系統調用<rt>syscall</rt></ruby>，最早由 OpenBSD 引入叫 <code>getentrypy(2)</code>，在 Linux 下這個叫 <code>getrandom(2)</code>。這個系統調用有着上述正確的行為：阻塞到有足夠的熵為止，然後再也不阻塞了。當然，這是個系統調用，而不是一個字節設備（LCTT 譯註：不在 <code>/dev/</code> 下），所以它在 shell 或者別的腳本語言裏沒那麼容易獲取。這個系統調用 自 Linux 3.17 起存在。</p></blockquote><p>在 Linux 上其實這個問題不太大，因為 Linux 發行版會在啓動的過程中保存一點隨機數（這發生在已經有一些熵之後，因為啓動程序不會在按下電源的一瞬間就開始運行）到一個種子文件中，以便系統下次啓動的時候讀取。所以每次啓動的時候系統都會從上一次會話裏帶一點隨機性過來。</p><p>顯然這比不上在關機腳本里寫入一些隨機種子，因為這樣的顯然就有更多熵可以操作了。但這樣做顯而易見的好處就是它不用關心繫統是不是正確關機了，比如可能你係統崩潰了。</p><p>而且這種做法在你真正第一次啓動系統的時候也沒法幫你隨機，不過好在 Linux 系統安裝程序一般會保存一個種子文件，所以基本上問題不大。</p><p>虛擬機是另外一層問題。因為用户喜歡克隆它們，或者恢復到某個之前的狀態。這種情況下那個種子文件就幫不到你了。</p><p>但解決方案依然和用 <code>/dev/random</code> 沒關係，而是你應該正確的給每個克隆或者恢復的鏡像重新生成種子文件。</p><h3 id="太長不看" tabindex="-1">太長不看 <a class="header-anchor" href="#太長不看" aria-label="Permalink to “太長不看”">​</a></h3><p>別問，問就是用 <code>/dev/urandom</code> !</p><hr>',15)),d("p",null,[e[16]||(e[16]=o("via: ",-1)),n(a,{href:"https://www.2uo.de/myths-about-urandom/"},{default:r(()=>[...e[15]||(e[15]=[o("https://www.2uo.de/myths-about-urandom/",-1)])]),_:1})]),d("p",null,[e[20]||(e[20]=o("作者：",-1)),n(a,{href:"https://www.2uo.de/"},{default:r(()=>[...e[17]||(e[17]=[o("Thomas Hühn",-1)])]),_:1}),e[21]||(e[21]=o(" 譯者：",-1)),n(a,{href:"https://github.com/Moelf"},{default:r(()=>[...e[18]||(e[18]=[o("Moelf",-1)])]),_:1}),e[22]||(e[22]=o(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[19]||(e[19]=[o("wxy",-1)])]),_:1})]),d("p",null,[e[25]||(e[25]=o("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[23]||(e[23]=[o("LCTT",-1)])]),_:1}),e[26]||(e[26]=o(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:r(()=>[...e[24]||(e[24]=[o("Linux中國",-1)])]),_:1}),e[27]||(e[27]=o(" 榮譽推出",-1))])])}const S=t(i,[["render",c]]);export{P as __pageData,S as default};
